 https://bun.report/1.2.10/Mr1db2e7d7kIiggQ_________u92oiBA2gnuDwugkod

Trace/BPT trap: 5
```

The issues I noticed:

1. Kuzu lacks TypeScript types, it would be great to have them on the package of by adding them through a package (`@types/kuzu`).
2. Kuzu's FTS index only indexes the existing entries, and not the new entries that are added to the table. I noticed the Vector search documentation clarifies this but the FTS does not, as far as I can tell. In any case, not having the ability to add entries to the index drastically limits the usability of the index.
3. Bun crashes with a segfault on exit, although everything seems to work before exit.
4. Extension installation seems to be running an HTTP request? "fts has been installed from repo: http://extension.kuzudb.com/". It was a bit surprising to see this, also it seems like the extension is not cached so the download happens on each install? It would be great if there was a way to ensure an app with FTS installed could run without making that request, perhaps by installing the extension directly from an NPM package, to avoid the HTTP request.

Thank you!

### Are there known steps to reproduce?

```database.ts

// @ts-ignore(no types);
import * as kuzu from 'kuzu';
import path from 'node:path';

const DATA_PATH = path.join(__dirname, './data');

export class DB {
  constructor(public readonly db = new kuzu.Database(DATA_PATH)) { }

  #initialized = false;

  async newConn() {
    if (!this.#initialized) {
      await this.#initialize(new kuzu.Connection(this.db));
      this.#initialized = true;
    }
    return await new kuzu.Connection(this.db);
  }

  async #initialize(conn: kuzu.Connection): Promise<void> {
    await conn.query(`//cypher
      INSTALL FTS;
      LOAD EXTENSION FTS;
    `);
  }

  async createNote(title: string, content: string): Promise<{ id: number, title: string, content: string }> {
    const conn = await this.newConn();
    const result = await conn.execute(await conn.prepare(`//cypher
      CREATE (n:Note {
        title: $title,
        content: $content
      })
      RETURN n.id as id, n.title as title, n.content as content
    `), { title, content });
    const notes = await result.getAll();
    await conn.close();

    return notes[0];
  }

  async getNoteById(id: number): Promise<{ id: number, title: string, content: string } | null> {
    const conn = await this.newConn();
    const result = await conn.execute(await conn.prepare(`//cypher
      MATCH (n:Note)
      WHERE n.id = $id
      RETURN n.id as id, n.title as title, n.content as content
    `), { id });
    const notes = await result.getAll();
    conn.close();

    return notes[0];
  }

  async getAllNotes(): Promise<Array<{ id: number, title: string, content: string }>> {
    const conn = await this.newConn();
    const result = await conn.query(`//cypher
      MATCH (n:Note)
      RETURN n.id as id, n.title as title, n.content as content
      ORDER BY n.id
    `);
    const notes = await result.getAll();
    conn.close();

    return notes;
  }

  async updateNote(id: number, title?: string, content?: string): Promise<{ id: number, title: string, content: string } | null> {
    const note = await this.getNoteById(id);
    if (!note) return null;

    let updateClause = '';
    const params: Record<string, any> = { id };

    if (title !== undefined) {
      updateClause += 'n.title = $title';
      params.title = title;
    }

    if (content !== undefined) {
      if (updateClause.length > 0) {
        updateClause += ', ';
      }
      updateClause += 'n.content = $content';
      params.content = content;
    }

    if (updateClause.length === 0) return note;

    const conn = await this.newConn();
    const result = await conn.execute(await conn.prepare(`//cypher
      MATCH (n:Note)
      WHERE n.id = $id
      SET ${updateClause}
      RETURN n.id as id, n.title as title, n.content as content
    `), params);
    conn.close();

    const updatedNote = result.getRow(0);
    return { id: updatedNote['n.id'], title: updatedNote['n.title'], content: updatedNote['n.content'] };
  }

  async deleteNote(id: number): Promise<boolean> {
    const conn = await this.newConn();
    const result = await conn.query(await conn.prepare(`//cypher
      MATCH (n:Note)
      WHERE n.id = $id
      DELETE n
      RETURN count(*) as deleted
    `), { id });
    conn.close();

    return result.getRow(0).deleted > 0;
  }

  async ftsNotes(searchTerm: string): Promise<Array<{ id: number, title: string, content: string, score: number }>> {
    const conn = await this.newConn();
    const result = await conn.execute(await conn.prepare(`//cypher
      CALL QUERY_FTS_INDEX('Note', 'Note_index', $searchTerm)
      RETURN node.id as id, node.title as title, node.content as content, score
      ORDER BY score DESC
    `), { searchTerm });
    const notes = await result.getAll();
    conn.close();

    return notes;
  }

  async close(): Promise<void> {
    await this.db.close();
    console.log('Database connection closed');
  }
}

export async function initDB(db: DB) {
  const conn = await db.newConn();

  await conn.query(`//cypher
    CREATE NODE TABLE IF NOT EXISTS Note (
      id SERIAL PRIMARY KEY,
      title STRING,
      content STRING
    )
  `);

  try {
    await conn.query(`//cypher
    CALL CREATE_FTS_INDEX('Note', 'Note_index', ['title', 'content']);
  `);
  } catch (error) {
    console.log(error);
  }

  await conn.close();
}

export async function seed(db: DB): Promise<void> {
  const sampleNotes = [
    { title: 'Getting Started with Kuzu', content: 'Kuzu is a high-performance graph database with excellent query capabilities.' },
    { title: 'TypeScript Tips', content: 'TypeScript adds static typing to JavaScript, making your code more robust.' },
    { title: 'Graph Database Concepts', content: 'Nodes and edges are the fundamental building blocks of graph databases.' },
    { title: 'Project Ideas', content: 'Building a note-taking app with full-text search capabilities using Kuzu.' },
    { title: 'Learning Resources', content: 'Documentation, tutorials, and community forums are great ways to learn new technologies.' }
  ];

  for (const note of sampleNotes) {
    await db.createNote(note.title, note.content);
  }

  console.log('Sample data seeded successfully');
}

(async () => {
  const db = new DB();
  await initDB(db);
  await seed(db);
  console.log(await db.getAllNotes());
  console.log(await db.ftsNotes('robust'));
  console.log(await db.ftsNotes("resource"));
})();
```

